// Domain Layer - User Entity
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

export interface UserProps {
  email: string;
  passwordHash: string;
}

// Domain Layer - Domain Errors
export type UserError = 
  | { type: 'InvalidEmail' }
  | { type: 'UserAlreadyExists' };

// Domain Layer - Use Case
export interface RegisterUserUseCase {
  execute(request: RegisterUserRequest): Promise<Result<User, UserError>>;
}

export interface RegisterUserRequest {
  email: string;
  password: string;
}

// Application Layer - Use Case Implementation
export class RegisterUser implements RegisterUserUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly emailService: IEmailService,
    private readonly passwordHasher: PasswordHasher
  ) {}

  async execute(request: RegisterUserRequest): Promise<Result<User, UserError>> {
    // Validate email
    if (!this.isValidEmail(request.email)) {
      return Result.failure({ type: 'InvalidEmail' });
    }

    // Check if user exists
    const existingUser = await this.userRepository.findByEmail(request.email);
    if (existingUser) {
      return Result.failure({ type: 'UserAlreadyExists' });
    }

    // Hash password
    const passwordHash = await this.passwordHasher.hash(request.password);

    // Create user
    const user: User = {
      id: crypto.randomUUID(),
      email: request.email,
      passwordHash
    };

    // Save user
    const savedUser = await this.userRepository.save(user);

    // Send welcome email
    await this.emailService.sendWelcomeEmail(user.email);

    return Result.success(savedUser);
  }

  private isValidEmail(email: string): boolean {
    return email.includes('@');
  }
}

// Application Layer - Ports
export interface IUserRepository {
  findByEmail(email: string): Promise<User | null>;
  save(user: User): Promise<User>;
}

export interface IEmailService {
  sendWelcomeEmail(to: string): Promise<void>;
}

// Application Layer - Password Hasher Interface
export interface PasswordHasher {
  hash(password: string): Promise<string>;
}

// Infrastructure Layer - Repository Implementation
export class PostgresUserRepository implements IUserRepository {
  constructor(private readonly db: DatabaseClient) {}

  async findByEmail(email: string): Promise<User | null> {
    const result = await this.db.query(
      'SELECT id, email, password_hash FROM users WHERE email = $1',
      [email]
    );

    if (result.rows.length === 0) {
      return null;
    }

    const row = result.rows[0];
    return {
      id: row.id,
      email: row.email,
      passwordHash: row.password_hash
    };
  }

  async save(user: User): Promise<User> {
    const result = await this.db.query(
      'INSERT INTO users(id, email, password_hash) VALUES($1, $2, $3) RETURNING id, email, password_hash',
      [user.id, user.email, user.passwordHash]
    );

    const row = result.rows[0];
    return {
      id: row.id,
      email: row.email,
      passwordHash: row.password_hash
    };
  }
}

// Infrastructure Layer - Email Service Implementation
export class SendGridEmailService implements IEmailService {
  constructor(private readonly sendgrid: SendGridClient) {}

  async sendWelcomeEmail(to: string): Promise<void> {
    await this.sendgrid.send({
      to,
      subject: 'Welcome',
      text: 'Welcome to our platform!'
    });
  }
}

// Infrastructure Layer - Password Hasher Implementation
export class BcryptPasswordHasher implements PasswordHasher {
  async hash(password: string): Promise<string> {
    return await bcrypt.hash(password, 10);
  }
}

// Presentation Layer - Express Route Handler
export class UserRouteHandler {
  constructor(
    private readonly registerUserUseCase: RegisterUserUseCase
  ) {}

  async handleRegister(req: Request, res: Response): Promise<void> {
    const { email, password } = req.body;

    const result = await this.registerUserUseCase.execute({
      email,
      password
    });

    if (result.isFailure()) {
      const error = result.error;
      switch (error.type) {
        case 'InvalidEmail':
          res.status(400).send('Invalid email');
          return;
        case 'UserAlreadyExists':
          res.status(409).send('User exists');
          return;
      }
    }

    const user = result.value;
    res.status(201).json({ id: user.id });
  }
}

