// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly customerId: string;
  readonly planId: string;
  readonly startDate: Date;
  readonly endDate: Date;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export class SubscriptionStatusError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionStatusError';
  }
}

export class SubscriptionValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionValidationError';
  }
}

// Domain/ValueObjects/SubscriptionValidator.ts
export class SubscriptionValidator {
  static validateCancelSubscription(subscription: Subscription): void {
    if (subscription.status === 'expired') {
      throw new SubscriptionStatusError('Cannot cancel an expired subscription');
    }

    if (subscription.status === 'cancelled') {
      throw new SubscriptionStatusError('Subscription is already cancelled');
    }
  }
}

// Application/UseCases/CancelSubscriptionUseCase.ts
import { Result, ok, error } from '../Result';
import { Subscription, SubscriptionStatusError } from '../Entities/Subscription';
import { SubscriptionValidator } from '../ValueObjects/SubscriptionValidator';

export interface CancelSubscriptionRequest {
  subscriptionId: string;
  customerId: string;
  cancelledAt: Date;
}

export interface CancelSubscriptionResponse {
  subscription: Subscription;
  message: string;
}

export class CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(
    request: CancelSubscriptionRequest
  ): Promise<Result<CancelSubscriptionResponse, SubscriptionStatusError>> {
    try {
      // Validate request
      if (!request.subscriptionId || !request.customerId) {
        return error(new SubscriptionValidationError('Invalid request parameters'));
      }

      // Get subscription from repository
      const subscription = await this.subscriptionRepository.findById(
        request.subscriptionId
      );

      if (!subscription) {
        return error(new SubscriptionValidationError('Subscription not found'));
      }

      // Validate customer ownership
      if (subscription.customerId !== request.customerId) {
        return error(new SubscriptionValidationError('Unauthorized to cancel this subscription'));
      }

      // Validate cancellation rules
      SubscriptionValidator.validateCancelSubscription(subscription);

      // Update subscription status
      const updatedSubscription = {
        ...subscription,
        status: 'cancelled' as const,
        updatedAt: request.cancelledAt
      };

      // Save updated subscription
      await this.subscriptionRepository.update(updatedSubscription);

      return ok({
        subscription: updatedSubscription,
        message: 'Subscription cancelled successfully'
      });
    } catch (err) {
      if (err instanceof SubscriptionStatusError) {
        return error(err);
      }

      if (err instanceof SubscriptionValidationError) {
        return error(err);
      }

      return error(new SubscriptionValidationError('Failed to cancel subscription'));
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  update(subscription: Subscription): Promise<void>;
}
