    try {
      // Validate order
      const order: Order = {
        id: request.id,
        items: request.items,
        total: request.total,
        tax: 0,
        createdAt: new Date()
      };

      this.orderService.validateOrder(order);

      // Calculate tax
      order.tax = this.orderService.calculateTax(order.total);

      // Save order
      await this.orderRepository.save(order);

      return ok({
        orderId: order.id,
        tax: order.tax
      });
    } catch (err) {
      if (err instanceof OrderError) {
        return error(err);
      }
      return error(new InvalidOrderError('Failed to process order'));
    }
  }
