   * @param transactionId - The transaction identifier to refund
   * @param amount - The refund amount in cents
   * @returns Refund result with refund details or error
   */
  refundPayment(
    transactionId: string,
    amount: number
  ): PaymentResult<RefundTransaction>;
}

