```typescript
// Domain Layer - User Entity
export class User {
  constructor(
    public readonly id: string,
    public readonly email: string,
    public readonly passwordHash: string
  ) {}
}

// Domain Layer - Domain Errors
export class UserError {
  static readonly EMAIL_INVALID = 'EMAIL_INVALID';
  static readonly USER_EXISTS = 'USER_EXISTS';
}

// Application Layer - Use Case
export interface RegisterUserUseCase {
  execute(request: RegisterUserRequest): Promise<Result<RegisterUserResponse, UserError>>;
}

export interface RegisterUserRequest {
  email: string;
  password: string;
}

export interface RegisterUserResponse {
  id: string;
}

// Application Layer - Use Case Implementation
export class RegisterUserUseCaseImpl implements RegisterUserUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly emailService: IEmailService
  ) {}

  async execute(request: RegisterUserRequest): Promise<Result<RegisterUserResponse, UserError>> {
    // Validate email
    if (!request.email.includes('@')) {
      return Result.failure(UserError.EMAIL_INVALID);
    }

    // Check if user exists
    const existingUser = await this.userRepository.findByEmail(request.email);
    if (existingUser) {
      return Result.failure(UserError.USER_EXISTS);
    }

    // Create user
    const user = await this.userRepository.create({
      email: request.email,
      passwordHash: await this.hashPassword(request.password)
    });

    // Send welcome email
    await this.emailService.sendWelcomeEmail(user.email);

    return Result.success({ id: user.id });
  }

  private async hashPassword(password: string): Promise<string> {
    // This would typically be injected as a dependency
    return bcrypt.hash(password, 10);
  }
}

// Infrastructure Layer - Repository Interface
export interface IUserRepository {
  findByEmail(email: string): Promise<User | null>;
  create(user: Omit<User, 'id'>): Promise<User>;
}

// Infrastructure Layer - Email Service Interface
export interface IEmailService {
  sendWelcomeEmail(to: string): Promise<void>;
}

// Infrastructure Layer - Repository Implementation
export class UserRepositoryImpl implements IUserRepository {
  constructor(private readonly db: DatabaseClient) {}

  async findByEmail(email: string): Promise<User | null> {
    const result = await this.db.query(
      'SELECT id, email, password FROM users WHERE email = $1',
      [email]
    );

    if (result.rows.length === 0) {
      return null;
    }

    const row = result.rows[0];
    return new User(row.id, row.email, row.password);
  }

  async create(user: Omit<User, 'id'>): Promise<User> {
    const result = await this.db.query(
      'INSERT INTO users(email, password) VALUES($1, $2) RETURNING id',
      [user.email, user.passwordHash]
    );

    return new User(result.rows[0].id, user.email, user.passwordHash);
  }
}

// Infrastructure Layer - Email Service Implementation
