import { Order } from '../../Domain/Entities/Order';
import { OrderError } from '../../Domain/Errors/OrderErrors';
import { TaxCalculator } from '../../Domain/ValueObjects/TaxCalculator';

export interface ProcessOrderRequest {
  id: string;
  items: OrderItem[];
  total: number;
