export class ProcessOrderUseCase {
  constructor(
    private readonly orderRepository: OrderRepository,
    private readonly notificationService: NotificationService
  ) {}

  async execute(request: ProcessOrderRequest): Promise<Result<Order, OrderError>> {
    // 1. Validate data
    const validation = this.validateOrder(request);
    if (validation.isError) {
      return error(validation.error);
    }

    // 2. Calculate tax
    const tax = TaxCalculator.calculateTax(request.total);

    // 3. Create order entity
    const order = new Order(
      request.id,
      request.items,
      request.total,
      tax
    );

    // 4. Save order
    const saveResult = await this.orderRepository.save(order);
    if (saveResult.isError) {
      return error(saveResult.error);
    }

    // 5. Send notification
    const notificationResult = await this.notificationService.sendOrderNotification(order.id);
    if (notificationResult.isError) {
      // Log error but don't fail the order processing
      console.error('Failed to send notification:', notificationResult.error);
    }

    return ok(saveResult.value);
  }

  private validateOrder(request: ProcessOrderRequest): Result<void, OrderError> {
    if (!request.items || request.items.length === 0) {
      return error(new EmptyOrderError());
    }

    if (request.total < 0) {
      return error(new InvalidOrderError('Total cannot be negative'));
    }

    return ok(undefined);
  }
}
