    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  isExpired(): boolean {
    return this.status === 'expired';
  }

  isCancelled(): boolean {
    return this.status === 'cancelled';
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

