export class ChangePasswordUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly passwordHasher: IPasswordHasher
  ) {}

  public async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    try {
      // Validate input
      if (!request.userId) {
        return Err(new InvalidPasswordError('User ID is required'));
      }

      if (!request.currentPassword) {
        return Err(new InvalidPasswordError('Current password is required'));
      }

      if (!request.newPassword) {
        return Err(new InvalidPasswordError('New password is required'));
      }

      // Check if user exists
      const user = await this.userRepository.findById(request.userId);
      if (!user) {
        return Err(new UserNotFoundError('User not found'));
      }

      // Verify current password
      const isPasswordValid = await this.passwordHasher.compare(
        request.currentPassword,
        user.getPasswordHash()
      );

      if (!isPasswordValid) {
        return Err(new PasswordMismatchError('Current password is incorrect'));
      }

      // Check if new password is different from old password
      const isNewPasswordSame = await this.passwordHasher.compare(
        request.newPassword,
        user.getPasswordHash()
      );

      if (isNewPasswordSame) {
        return Err(new InvalidPasswordError('New password cannot be the same as the current password'));
      }

      // Hash new password
      const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

      // Update user password
      user.setPasswordHash(newPasswordHash);
      await this.userRepository.save(user);

      return Ok(undefined);
    } catch (error) {
      if (error instanceof DomainError) {
        return Err(error);
      }
      return Err(new InvalidPasswordError('Failed to change password'));
    }
  }
