// Domain layer - User entity and domain errors
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

export type UserError = 
  | { type: 'InvalidEmail' }
  | { type: 'UserAlreadyExists' };

// Application layer - Use case
export interface RegisterUserUseCase {
  execute(email: string, password: string): Promise<Result<User, UserError>>;
}

// Infrastructure layer - Repository interface
export interface IUserRepository {
  findByEmail(email: string): Promise<User | null>;
  save(user: User): Promise<User>;
}

// Infrastructure layer - Email service interface
export interface IEmailService {
  sendWelcomeEmail(to: string): Promise<void>;
}

// Application layer - Concrete use case implementation
export class RegisterUser implements RegisterUserUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly emailService: IEmailService
  ) {}

  async execute(email: string, password: string): Promise<Result<User, UserError>> {
    // Validate email
    if (!email.includes('@')) {
      return Result.failure({ type: 'InvalidEmail' });
    }

    // Check if user exists
    const existingUser = await this.userRepository.findByEmail(email);
    if (existingUser) {
      return Result.failure({ type: 'UserAlreadyExists' });
    }

    // Hash password and create user
    const passwordHash = await bcrypt.hash(password, 10);
    const user: User = {
      id: crypto.randomUUID(),
      email,
      passwordHash
    };

    try {
      const savedUser = await this.userRepository.save(user);

      // Send welcome email
      await this.emailService.sendWelcomeEmail(email);

      return Result.success(savedUser);
    } catch (error) {
      // Handle repository or email service errors
      throw error; // Or convert to specific domain error
    }
  }
}

// Infrastructure layer - Express route handler
export const registerUserRoute = (
  registerUserUseCase: RegisterUserUseCase
) => {
  return async (req: Request, res: Response) => {
    try {
      const { email, password } = req.body;

      const result = await registerUserUseCase.execute(email, password);

      if (result.isFailure()) {
        const error = result.error;
        switch (error.type) {
          case 'InvalidEmail':
            return res.status(400).send('Invalid email');
          case 'UserAlreadyExists':
            return res.status(409).send('User exists');
        }
      }

      const user = result.value;
      res.status(201).json({ id: user.id });
    } catch (error) {
      console.error('Registration error:', error);
      res.status(500).send('Internal server error');
    }
  };
};

