## The Problem: Active Record with Embedded Business Logic

Here's an example of problematic code where business rules are tightly coupled to persistence:

```typescript
// ❌ BAD: Active Record with embedded business logic
class Order {
  private _status: OrderStatus = OrderStatus.PENDING;
  private _totalAmount: number = 0;
  private _items: OrderItem[] = [];

  // ORM lifecycle hook - business logic embedded here
  beforeSave(): void {
    // Business rule #1: Order must have at least one item
    if (this._items.length === 0) {
      throw new Error('Order must have at least one item');
    }

    // Business rule #2: Total amount must be positive
    if (this._totalAmount <= 0) {
      throw new Error('Total amount must be positive');
    }

    // Business rule #3: Status transition validation
    if (this._status === OrderStatus.PAID && this._totalAmount <= 0) {
      throw new Error('Cannot mark order as paid with zero amount');
    }

    // Business rule #4: Validation based on customer type
    if (this.customerType === CustomerType.VIP && this._totalAmount < 1000) {
      throw new Error('VIP orders must be at least $1000');
    }
  }

  // This violates the dependency rule - domain layer depends on infrastructure
  save(): void {
    this.beforeSave(); // Business logic tied to persistence
    // Database persistence logic here
  }
}
```

## The Solution: Clean Architecture Refactoring

Here's how to properly separate domain invariants from persistence:

### 1. Domain Layer (Pure Business Rules)

```typescript
// Domain Entities
interface OrderItem {
  productId: string;
  quantity: number;
  price: number;
}

interface Order {
  id: string;
  status: OrderStatus;
  totalAmount: number;
  items: OrderItem[];
  customerId: string;
  customerType: CustomerType;
}

// Domain Errors
type OrderError = 
  | { type: 'EmptyItems' }
  | { type: 'InvalidAmount' }
  | { type: 'InvalidStatusTransition' }
  | { type: 'InsufficientAmountForVIP' }
  | { type: 'InvalidOrderStatus' };

// Domain Service for Business Rules
class OrderValidationService {
  validateOrder(order: Order): Result<Order, OrderError> {
    // Rule 1: Order must have at least one item
    if (order.items.length === 0) {
      return Result.failure({ type: 'EmptyItems' });
    }

    // Rule 2: Total amount must be positive
    if (order.totalAmount <= 0) {
      return Result.failure({ type: 'InvalidAmount' });
    }

    // Rule 3: Status transition validation
    if (order.status === OrderStatus.PAID && order.totalAmount <= 0) {
      return Result.failure({ type: 'InvalidStatusTransition' });
    }

    // Rule 4: VIP customer validation
    if (order.customerType === CustomerType.VIP && order.totalAmount < 1000) {
      return Result.failure({ type: 'InsufficientAmountForVIP' });
    }

    return Result.success(order);
  }

  validateStatusTransition(
    currentStatus: OrderStatus, 
    newStatus: OrderStatus
  ): Result<void, OrderError> {
    // Status transition business rules
    if (currentStatus === OrderStatus.PAID && newStatus === OrderStatus.PENDING) {
      return Result.failure({ type: 'InvalidStatusTransition' });
    }

    return Result.success(undefined);
  }
}

// Domain Value Objects
