  PENDING = 'PENDING',
  PAID = 'PAID',
  SHIPPED = 'SHIPPED',
  DELIVERED = 'DELIVERED',
  CANCELLED = 'CANCELLED'
}

enum CustomerType {
  REGULAR = 'REGULAR',
  VIP = 'VIP'
}
