      return Result.success({
        paymentId: stripePayment.id,
        status: this.mapStripeStatus(stripePayment.status),
        amount: stripePayment.amount / 100, // Convert back to dollars
        currency: stripePayment.currency,
        createdAt: new Date(stripePayment.created * 1000),
        transactionId: stripePayment.latest_charge?.id,
      });

    } catch (error: unknown) {
      return Result.error(this.mapStripeError(error));
    }
