export class CancelSubscriptionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CancelSubscriptionError';
  }
}

export class CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(
    request: CancelSubscriptionRequest
  ): Promise<Result<CancelSubscriptionResponse, CancelSubscriptionError>> {
    try {
      // Validate request
      if (!request.subscriptionId) {
        return Err(new CancelSubscriptionError('Subscription ID is required'));
      }

      if (!request.cancelledAt) {
        return Err(new CancelSubscriptionError('Cancelled date is required'));
      }

      // Fetch subscription
      const subscriptionResult = await this.subscriptionRepository.findById(
        request.subscriptionId
      );

      if (subscriptionResult.isErr()) {
        return Err(subscriptionResult.error);
      }

      const subscription = subscriptionResult.value;

      // Validate business rules
      const validationError = this.validateCancellation(subscription);
      if (validationError) {
        return Err(validationError);
      }

      // Update subscription status
      const updatedSubscription = this.updateSubscriptionStatus(
        subscription,
        request.cancelledAt
      );

      // Save updated subscription
      const saveResult = await this.subscriptionRepository.save(updatedSubscription);
      if (saveResult.isErr()) {
        return Err(saveResult.error);
      }

      return Ok({
        subscription: updatedSubscription,
        cancelledAt: request.cancelledAt
      });
    } catch (error) {
      if (error instanceof CancelSubscriptionError) {
        return Err(error);
      }
      return Err(new CancelSubscriptionError('Failed to cancel subscription'));
    }
  }

  private validateCancellation(subscription: Subscription): CancelSubscriptionError | null {
    // Cannot cancel already expired subscription
    if (subscription.status === 'expired') {
      return new CancelSubscriptionError('Cannot cancel an expired subscription');
    }

    // Cannot cancel already cancelled subscription
    if (subscription.status === 'cancelled') {
      return new CancelSubscriptionError('Cannot cancel an already cancelled subscription');
    }

    // Additional business rules can be added here
    return null;
  }

  private updateSubscriptionStatus(
    subscription: Subscription,
    cancelledAt: Date
  ): Subscription {
    return {
      ...subscription,
      status: 'cancelled',
      updatedAt: cancelledAt
    };
  }
}

