## The Problem: Active Record with Embedded Business Rules

Here's an example of problematic code where business logic is tightly coupled to persistence:

```typescript
// ❌ BAD: Active Record with embedded business rules
class Order {
  id: string;
  status: 'pending' | 'processing' | 'shipped' | 'delivered';
  items: OrderItem[];
  totalAmount: number;
  createdAt: Date;
  updatedAt: Date;

  constructor(
    id: string,
    status: 'pending' | 'processing' | 'shipped' | 'delivered',
    items: OrderItem[],
    totalAmount: number
  ) {
    this.id = id;
    this.status = status;
    this.items = items;
    this.totalAmount = totalAmount;
    this.createdAt = new Date();
    this.updatedAt = new Date();
  }

  // ❌ Business logic embedded in persistence lifecycle
  beforeSave() {
    // Business rule: Order must have at least one item
    if (this.items.length === 0) {
      throw new Error('Order must have at least one item');
    }

    // Business rule: Order total must be positive
    if (this.totalAmount <= 0) {
      throw new Error('Order total must be positive');
    }

    // Business rule: Status transition validation
    if (this.status === 'shipped' && this.items.some(item => item.quantity <= 0)) {
      throw new Error('Cannot ship order with zero quantity items');
    }

    // Business rule: Only pending orders can be modified
    if (this.status !== 'pending' && this.status !== 'processing') {
      throw new Error('Cannot modify orders that are not pending or processing');
    }

    // Business rule: Total amount calculation validation
    const calculatedTotal = this.items.reduce((sum, item) => 
      sum + (item.price * item.quantity), 0);

    if (Math.abs(calculatedTotal - this.totalAmount) > 0.01) {
      throw new Error('Total amount does not match calculated amount');
    }

    this.updatedAt = new Date();
  }
}
