    try {
      const result = await this.db.query(
        'SELECT id, email, password FROM users WHERE email = $1',
        [email]
      );

      if (result.rows.length === 0) {
        return Result.success<User | null, UserError>(null);
      }

      const row = result.rows[0];
      return Result.success<User | null, UserError>({
        id: row.id,
        email: row.email,
        passwordHash: row.password
      });
    } catch (error) {
      // Map database errors to domain errors
      return Result.failure<User | null, UserError>({ type: 'InvalidEmail' });
    }
  }

  async save(user: User): Promise<Result<User, UserError>> {
    try {
      const result = await this.db.query(
        'INSERT INTO users(email, password) VALUES($1, $2) RETURNING id',
        [user.email, user.passwordHash]
      );

      return Result.success<User, UserError>({
        ...user,
        id: result.rows[0].id
      });
    } catch (error) {
      // Map database errors to domain errors
      return Result.failure<User, UserError>({ type: 'UserAlreadyExists' });
