/**
 * In-memory test double implementation of IEventPublisher
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private readonly publishedEvents: IDomainEvent[] = [];
  private readonly errorOnPublish: boolean = false;
  private readonly errorToThrow: EventPublishingError;

  constructor(
    errorOnPublish: boolean = false,
    errorToThrow?: EventPublishingError
  ) {
    this.errorOnPublish = errorOnPublish;
    this.errorToThrow = errorToThrow || new EventPublishingError("Failed to publish event");
  }

  async publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    if (this.errorOnPublish) {
      return Result.failure(this.errorToThrow);
    }

    this.publishedEvents.push(event);
    return Result.success(undefined);
  }

  /**
   * Gets all published events for testing assertions
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.publishedEvents];
  }

  /**
   * Clears the published events collection
   */
  clear(): void {
    this.publishedEvents.length = 0;
  }

  /**
   * Checks if an event was published
   */
  wasEventPublished(eventType: string): boolean {
    return this.publishedEvents.some(event => event.eventType === eventType);
  }
}

// Result type implementation (for completeness)

/**
 * Result type for handling success/failure scenarios
 */
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  static success<T>(value: T): Result<T, never> {
    return new Result<T, never>(true, value);
  }

  static failure<E extends Error>(error: E): Result<never, E> {
    return new Result<never, E>(false, undefined, error);
  }
}
