    this._totalAmount = this.calculateTotal();
  }

  // ❌ Business logic embedded in lifecycle hook
  beforeSave(): void {
    // Business rule: Order must have at least one item
    if (this._items.length === 0) {
      throw new Error("Order must have at least one item");
    }

    // Business rule: Customer must be active
    const customer = CustomerRepository.findById(this.customerId);
    if (!customer || !customer.isActive) {
      throw new Error("Customer must be active");
    }

    // Business rule: Total amount must be positive
    if (this._totalAmount <= 0) {
      throw new Error("Total amount must be positive");
    }

    // Business rule: Order status must be valid
    if (!this.isValidStatus(this._status)) {
      throw new Error("Invalid order status");
    }

    // Business rule: Order cannot be modified after 24 hours
    const now = new Date();
    const timeDiff = now.getTime() - this.createdAt.getTime();
    if (timeDiff > 24 * 60 * 60 * 1000) {
      throw new Error("Order cannot be modified after 24 hours");
    }
  }

  private calculateTotal(): number {
    return this._items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  }

  private isValidStatus(status: OrderStatus): boolean {
    return [OrderStatus.PENDING, OrderStatus.CONFIRMED, OrderStatus.SHIPPED].includes(status);
  }

  // More methods...
