## The Solution: Clean Architecture Refactoring

### 1. Domain Layer (Pure Business Logic)

```typescript
// Domain Entities
export interface OrderId {
  value: string;
}

export enum OrderStatus {
  PENDING = 'PENDING',
  HIGH_VALUE = 'HIGH_VALUE',
  CONFIRMED = 'CONFIRMED',
  CANCELLED = 'CANCELLED'
}

export interface OrderItem {
  productId: string;
  quantity: number;
  price: number;
}

export interface Customer {
  id: string;
  isBlocked(): boolean;
}

// Domain Entity
export class Order {
  private _status: OrderStatus = OrderStatus.PENDING;
  private _items: OrderItem[] = [];
  private _totalAmount: number = 0;

  constructor(
    private readonly _id: OrderId,
    private readonly _customer: Customer
  ) {}

  // Pure domain business rules
  static create(
    id: OrderId,
    customer: Customer,
    items: OrderItem[]
  ): Result<Order, OrderError> {
    if (items.length === 0) {
      return Result.failure(new OrderValidationError("Order must have at least one item"));
    }

    const order = new Order(id, customer);
    items.forEach(item => order.addItem(item));

    return Result.success(order);
  }

  addItem(item: OrderItem): void {
    this._items.push(item);
    this._totalAmount += item.price;
  }

  // Business rule: validate order before confirmation
  validate(): Result<void, OrderError> {
    if (this._items.length === 0) {
      return Result.failure(new OrderValidationError("Order must have at least one item"));
    }

    if (this._totalAmount <= 0) {
      return Result.failure(new OrderValidationError("Order total must be positive"));
    }

    if (this._customer.isBlocked()) {
      return Result.failure(new OrderValidationError("Cannot create order for blocked customer"));
    }

    return Result.success(undefined);
  }

  // Business rule: status transition
  applyStatusRules(): void {
    if (this._status === OrderStatus.PENDING && this._totalAmount >= 1000) {
      this._status = OrderStatus.HIGH_VALUE;
    }
  }

  get id(): OrderId {
    return this._id;
  }

  get status(): OrderStatus {
    return this._status;
  }

  get totalAmount(): number {
    return this._totalAmount;
  }

  get items(): OrderItem[] {
    return [...this._items];
  }
}
