import { Result, Ok, Err } from '../Result';
import { Subscription, SubscriptionStatusError } from '../../Domain/Entities/Subscription';

export interface CancelSubscriptionRequest {
  subscriptionId: string;
  customerId: string;
  cancelledAt: Date;
}

export interface CancelSubscriptionResponse {
  subscriptionId: string;
  status: 'cancelled';
  cancelledAt: Date;
}

export class CancelSubscriptionUseCase {
  constructor() {}

  execute(request: CancelSubscriptionRequest): Result<CancelSubscriptionResponse, SubscriptionError> {
    try {
      // Validate request
      if (!request.subscriptionId || !request.customerId) {
        return Err(new SubscriptionValidationError('Subscription ID and Customer ID are required'));
      }

      // In a real implementation, this would be retrieved from a repository
      // For this example, we'll simulate the domain entity
      const subscription: Subscription = this.getSubscription(request.subscriptionId);

      // Validate invariant rules
      if (subscription.status === 'expired') {
        return Err(new SubscriptionStatusError('Cannot cancel an expired subscription'));
      }

      if (subscription.status === 'cancelled') {
        return Err(new SubscriptionStatusError('Subscription is already cancelled'));
      }

      // Validate customer ownership
      if (subscription.customerId !== request.customerId) {
        return Err(new SubscriptionValidationError('Customer does not own this subscription'));
      }

      // Perform cancellation
      const cancelledSubscription: CancelSubscriptionResponse = {
        subscriptionId: subscription.id,
        status: 'cancelled',
        cancelledAt: request.cancelledAt
      };

      return Ok(cancelledSubscription);
    } catch (error) {
      if (error instanceof Error) {
        return Err(error as SubscriptionError);
      }
      return Err(new SubscriptionValidationError('Unknown error occurred during cancellation'));
    }
  }

  private getSubscription(subscriptionId: string): Subscription {
    // This would normally come from a repository
    // For demonstration purposes, we'll create a mock subscription
    return {
      id: subscriptionId,
      customerId: 'customer-123',
      status: 'active',
      startDate: new Date('2023-01-01'),
      endDate: new Date('2024-01-01'),
      createdAt: new Date('2023-01-01'),
      updatedAt: new Date('2023-01-01')
    };
  }
