  constructor(private readonly eventPublisher: IEventPublisher) {}

  async execute(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    return await this.eventPublisher.publish(event);
  }
}

// Infrastructure layer - Test Double Implementation

/**
 * In-memory test double implementation of IEventPublisher
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private readonly publishedEvents: IDomainEvent[] = [];
  private readonly error: EventPublishingError | null = null;

  /**
   * Creates a new instance of InMemoryEventPublisher
   * @param errorToThrow - Optional error to simulate publishing failure
   */
  constructor(errorToThrow?: EventPublishingError) {
    this.error = errorToThrow || null;
  }

  async publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    if (this.error) {
      return Result.failure(this.error);
    }

    this.publishedEvents.push(event);
    return Result.success(undefined);
  }

  /**
   * Gets all published events
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.publishedEvents];
  }

  /**
   * Clears all published events
   */
  clear(): void {
    this.publishedEvents.length = 0;
  }

  /**
   * Checks if an event was published
   */
  wasEventPublished(eventType: string): boolean {
    return this.publishedEvents.some(e => e.eventType === eventType);
  }
}

