class Failure<E extends Error> {
  constructor(public readonly error: E) {}

  isSuccess(): this is Success<T> {
    return false;
  }

  isFailure(): this is Failure<E> {
    return true;
  }

  static failure<E extends Error>(error: E): Result<never, E> {
    return new Failure(error);
  }
