    }
    return Result.success(undefined);
  }

  static validateStatusChange(
    oldStatus: UserStatus, 
    newStatus: UserStatus,
    hasApproval: boolean
  ): Result<void, UserError> {
    if (oldStatus !== newStatus && newStatus === 'suspended' && !hasApproval) {
      return Result.failure(new ApprovalRequiredError());
    }
    return Result.success(undefined);
  }
}

// Domain Service for Complex Business Logic
class UserService {
  static validateUserCreation(
    email: string,
    age: number,
    userRepository: UserRepository
