// Domain Layer - Interfaces and Types
export interface IPaymentGateway {
  /**
   * Processes a payment transaction
   * @param paymentRequest - Payment details
   * @returns Result containing payment response or error
   */
  processPayment(paymentRequest: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>>;
}

export interface PaymentRequest {
  amount: number;
  currency: string;
  customerId: string;
  paymentMethodId: string;
  description?: string;
}

export interface PaymentResponse {
  id: string;
  status: 'succeeded' | 'failed' | 'pending';
  amount: number;
  currency: string;
  customerId: string;
  createdAt: Date;
}

export type PaymentError = 
  | 'InsufficientFunds'
  | 'InvalidPaymentMethod'
  | 'PaymentProcessingFailed'
  | 'InvalidAmount'
  | 'UnknownError';

// Application Layer - Use Cases
import { IPaymentGateway } from '../domain/interfaces';

export interface ProcessPaymentUseCase {
  execute(request: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>>;
}

export class ProcessPayment implements ProcessPaymentUseCase {
  constructor(private readonly paymentGateway: IPaymentGateway) {}

  async execute(request: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>> {
    // Validate request
    if (request.amount <= 0) {
      return Result.failure('InvalidAmount');
    }

    // Delegate to payment gateway
    return await this.paymentGateway.processPayment(request);
  }
}

// Infrastructure Layer - Adapter Implementation
import { IPaymentGateway } from '../../domain/interfaces';
import Stripe from 'stripe';

export class StripePaymentAdapter implements IPaymentGateway {
  private readonly stripe: Stripe;

  constructor(stripeApiKey: string) {
    this.stripe = new Stripe(stripeApiKey, {
      apiVersion: '2023-10-16',
    });
  }

  async processPayment(paymentRequest: PaymentRequest): Promise<Result<PaymentResponse, PaymentError>> {
    try {
      const paymentIntent = await this.stripe.paymentIntents.create({
        amount: Math.round(paymentRequest.amount * 100), // Convert to cents
        currency: paymentRequest.currency,
        customer: paymentRequest.customerId,
        payment_method: paymentRequest.paymentMethodId,
        confirm: true,
        description: paymentRequest.description,
      });

      return Result.success({
        id: paymentIntent.id,
        status: paymentIntent.status as 'succeeded' | 'failed' | 'pending',
        amount: paymentIntent.amount / 100, // Convert back to dollars
        currency: paymentIntent.currency,
        customerId: paymentRequest.customerId,
        createdAt: new Date(paymentIntent.created * 1000),
      });
    } catch (error) {
      // Map Stripe errors to our domain errors
      if (error instanceof Error) {
        if (error.message.includes('insufficient funds')) {
          return Result.failure('InsufficientFunds');
        }
        if (error.message.includes('invalid payment method')) {
          return Result.failure('InvalidPaymentMethod');
        }
      }

      return Result.failure('PaymentProcessingFailed');
    }
  }
}

// Result Utility Type
export type Result<T, E> = SuccessResult<T> | FailureResult<E>;

interface SuccessResult<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface FailureResult<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export class Result<T, E> {
  private constructor(
    readonly isSuccess: boolean,
    readonly value?: T,
    readonly error?: E
  ) {}

  static success<T>(value: T): Result<T, never> {
    return new Result<T, never>(true, value);
  }

  static failure<E>(error: E): Result<never, E> {
    return new Result<never, E>(false, undefined, error);
  }
}
